export async function deleteCommentDocumentsForIssue(
  orgId: OrgId,
  issueId: string,
): Promise<void> {
  const db = getDb();
  const ids = db
    .select({ id: comments.id })
    .from(comments)
    .where(and(orgPredicate(comments.orgId, orgId), eq(comments.issueId, issueId)))
    .all()
    .map((row) => row.id);
  for (let i = 0; i < ids.length; i += 500) {
    db.delete(searchIndex)
      .where(
        and(
          orgPredicate(searchIndex.orgId, orgId),
          eq(searchIndex.subjectKind, "comment"),
          inArray(searchIndex.subjectId, ids.slice(i, i + 500)),
        ),
      )
      .run();
  }
}

/** Drops every indexed document of one org. */
export async function deleteAllForOrg(orgId: OrgId): Promise<void> {
  getDb()
    .delete(searchIndex)
    .where(orgPredicate(searchIndex.orgId, orgId))
    .run();
}

